def create_credential(
    self,
    tenant_id: str,
    issuer_did: str,
    subject_did: str,
    claims: Dict[str, Any],
    expires_at: Any = EXPIRES_AT_UNSET,
) -> CredentialRecord:
    """校验签发者/持有者 DID（限本租户），构造正文并签名，记审计。

    expires_at 省略（EXPIRES_AT_UNSET）时正文不含该字段，凭证无
    期限；提供时必须为 UTC 秒精度 Z 格式且严格晚于当前时刻，并原样
    写入正文参与 ES256 规范化签名。
    """
    if not isinstance(issuer_did, str) or not issuer_did:
        raise ValidationError("缺少字段或字段为空: issuer_did")
    if not isinstance(subject_did, str) or not subject_did:
        raise ValidationError("缺少字段或字段为空: subject_did")
    if not isinstance(claims, dict):
        raise ValidationError("字段 claims 必须为 JSON 对象")
    raw_expires_at = None
    if expires_at is not EXPIRES_AT_UNSET:
        raw_expires_at = _validate_future_utc_z(expires_at, "expires_at")

    with self._lock:
        bucket = self._ensure_bucket_locked(tenant_id)
        # 逐个指明不存在的是哪一个 DID（他租户 DID 同样不可见）
        issuer = bucket["dids"].get(issuer_did)
        if issuer is None:
            raise ValidationError(f"issuer_did 不存在: {issuer_did}")
        subject = bucket["dids"].get(subject_did)
        if subject is None:
            raise ValidationError(f"subject_did 不存在: {subject_did}")
        # 已停用 DID 不得再作为 issuer 签发凭证：409 且不写记录。
        if issuer.get("status") == "deactivated":
            raise ConflictError(f"签发者 DID 已停用，不能签发凭证: {issuer_did}")

        snapshot = self._snapshot_locked()
        try:
            credential_id = f"vc_{uuid.uuid4().hex}"
            body: Dict[str, Any] = {
                "credential_id": credential_id,
                "issuer_did": issuer_did,
                "subject_did": subject_did,
                "claims": claims,
                "issued_at": _utc_now(),
                "issuer_key_version": int(issuer.get("key_version", 1)),
            }
            # 仅在请求提供时写入：未提供不得注入字段（旧凭证无期限）。
            if raw_expires_at is not None:
                body["expires_at"] = raw_expires_at
            signature = crypto.sign(body, issuer["private_key_pem"])
            bucket["credentials"][credential_id] = {
                "body": body,
                "signature": signature,
            }
            self._append_audit_locked(
                tenant_id, AUDIT_CREDENTIAL_ISSUED,
                "credential", credential_id,
            )
            self._save_locked()
            return CredentialRecord(
                credential_id=credential_id, body=body, signature=signature
            )
        except Exception:
            self._restore_locked(snapshot)
            raise

def get_credential(
    self, tenant_id: str, credential_id: str
) -> CredentialRecord:
    """查询本租户凭证；不存在（含他租户资源）抛 NotFoundError。"""
    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        rec = (
            bucket["credentials"].get(credential_id)
            if bucket is not None else None
        )
        if rec is None:
            raise NotFoundError(f"凭证不存在: {credential_id}")
        return CredentialRecord(
            credential_id=credential_id,
            body=rec["body"],
            signature=rec["signature"],
        )

# ------------------------------------------------------------------ #
# 选择性披露演示
# ------------------------------------------------------------------ #
def _private_key_for_version_locked(
    self, bucket: Dict[str, Any], did: str, version: int
) -> Optional[str]:
    rec = bucket["dids"].get(did) if bucket is not None else None
    if rec is None:
        return None
    for entry in rec.get("key_history", []):
        if entry.get("version") == version:
            return entry.get("private_key_pem")
    return None

@staticmethod
def _presentation_record(row: Dict[str, Any]) -> PresentationRecord:
    return PresentationRecord(
        presentation_id=row["presentation_id"],
        credential_id=row["credential_id"],
        issuer_did=row["issuer_did"],
        issuer_key_version=int(row["issuer_key_version"]),
        disclose=list(row.get("disclose", [])),
        projection=row.get("claims", {}),
        proof=row["proof"],
        challenge=row.get("challenge"),
        expires_at=row.get("expires_at"),
        holder_did=row.get("holder_did"),
        holder_key_version=(
            int(row["holder_key_version"])
            if row.get("holder_key_version") is not None
            else None
        ),
        holder_proof=row.get("holder_proof"),
    )

def _build_presentation_row_locked(
    self,
    tenant_id: str,
    bucket: Optional[Dict[str, Any]],
    credential_id: str,
    disclose: Any,
    challenge: str,
    expires_at: str,
    holder_binding: bool,

def do_POST(self) -> None:  # noqa: N802 (BaseHTTPRequestHandler API)
    try:
        parsed = urlparse(self.path)
        path = parsed.path.rstrip("/") or "/"
        parsed_query = parsed.query
        if not path.startswith("/v1"):
            self._send_error(404, f"无此路径: {path}")
            return
        # 凭证状态回执消费（单条与批量）及凭证状态回执消费同步
        # 进度回执消费协议：显式空 X-Tenant-ID 一律 400 且仅
        # {"error": "请求非法"}（区别于其余入口的
        # “X-Tenant-ID 不能为空”）。
        if (
            path
            in (
                "/v1/trust/credential-status/receipt/consume",
                "/v1/trust/credential-status/receipt/consume-batch",
                "/v1/trust/credential-status/receipt-sync"
                "/receipt/consume",
                "/v1/trust/credential-status/receipt-sync"
                "/receipt/consume-batch",
                "/v1/trust/credentials/imported/verify-batch",
                "/v1/audit/manifest/verify-batch",
            )
            and self.headers.get("X-Tenant-ID") == ""
        ):
            raise ValidationError("请求非法")
        tenant = self._tenant_id()
        if path == "/v1/dids":
            self._post_dids(tenant)
        elif path == "/v1/audit/manifest/verify":
            self._post_audit_manifest_verify(tenant)
        elif path == "/v1/audit/manifest/verify-batch":
            self._post_audit_manifest_verify_batch(tenant)
        elif path == "/v1/credentials":
            self._post_credentials(tenant)
        elif path == "/v1/credentials/status-export":
            self._post_credentials_status_export(tenant)
        elif path == "/v1/credentials/revoke-batch":
            self._post_revoke_credentials_batch(tenant)
        elif path.startswith("/v1/dids/") and path.endswith(
            "/keys/rotate"
        ):
            did = unquote(
                path[len("/v1/dids/") : -len("/keys/rotate")]
            )
            self._post_rotate_key(tenant, did)
        elif path.startswith("/v1/dids/") and "/keys/" in path and path.endswith(
            "/revoke"
        ):
            middle = path[len("/v1/dids/") : -len("/revoke")]
            did_raw, sep, version_raw = middle.partition("/keys/")
            did = unquote(did_raw)
            key_version = unquote(version_raw) if sep else ""
            self._post_revoke_key(tenant, did, key_version)
        elif path.startswith("/v1/dids/") and path.endswith(
            "/deactivate"
        ):
            did = unquote(
                path[len("/v1/dids/") : -len("/deactivate")]
            )
            self._post_deactivate_did(tenant, did)
        elif path.startswith("/v1/credentials/") and path.endswith(
            "/revoke"
        ):
            credential_id = unquote(
                path[len("/v1/credentials/") : -len("/revoke")]
            )
            self._post_revoke_credential(tenant, credential_id)
        elif path.startswith("/v1/credentials/") and path.endswith(
            "/verify"
        ):
            credential_id = unquote(
                path[len("/v1/credentials/") : -len("/verify")]
            )
            self._post_verify_credential(
                tenant, credential_id
            )
        elif path.startswith("/v1/credentials/") and path.endswith(
            "/present"
        ):
            credential_id = unquote(
                path[len("/v1/credentials/") : -len("/present")]
            )
            self._post_present(tenant, credential_id)
        elif path.startswith("/v1/credentials/") and path.endswith(
            "/present-batch"
        ):
            credential_id = unquote(
                path[len("/v1/credentials/") : -len("/present-batch")]
            )
            self._post_present_batch(tenant, credential_id)
        elif path.startswith("/v1/credentials/") and path.endswith(
            "/prove"
        ):
            credential_id = unquote(
                path[len("/v1/credentials/") : -len("/prove")]
            )
            self._post_prove(tenant, credential_id)
        elif path.startswith("/v1/credentials/") and path.endswith(
            "/prove-batch"
        ):
            credential_id = unquote(
                path[len("/v1/credentials/") : -len("/prove-batch")]
            )
            self._post_prove_batch(tenant, credential_id)
        elif path.startswith("/v1/proofs/") and path.endswith(
            "/verify"
        ):
            proof_id = unquote(
                path[len("/v1/proofs/") : -len("/verify")]
            )
            self._post_verify_proof(tenant, proof_id)
        elif path == "/v1/presentations/multi":
            self._post_multi_presentations(tenant)
        elif path.startswith("/v1/presentations/") and path.endswith(
            "/verify"
        ):
            presentation_id = unquote(
                path[len("/v1/presentations/") : -len("/verify")]
            )
            self._post_verify_presentation(
                tenant, presentation_id
            )
        elif path == "/v1/trust/anchors":
            self._post_trust_anchors(tenant)
        elif path == "/v1/trust/anchors/snapshot/verify":
            self._post_trust_anchor_snapshot_verify(tenant)
        elif path == "/v1/trust/anchors/snapshot/verify-batch":
            self._post_trust_anchor_snapshot_verify_batch(tenant)

    # 重复吊销后校验（字符串裁剪后非空，否则 400），重复吊销时
    # 任何 reason（含非法值）均忽略并返回首次结果。
    if (
        not key_version
        or any(ch < "0" or ch > "9" for ch in key_version)
        or int(key_version) < 1
    ):
        raise ValidationError("路径参数 key_version 必须为 ASCII 十进制正整数")
    data = self._read_optional_json()
    if data:
        extra = sorted(set(data) - {"reason"})
        if extra:
            raise ValidationError(f"多余字段: {', '.join(extra)}")
        if "reason" not in data:
            raise ValidationError("请求体非空时必须恰含字段: reason")
    reason = data["reason"] if data and "reason" in data else REASON_UNSET
    record = store.revoke_key_version(
        tenant, did, int(key_version), reason
    )
    self._send_json(
        200,
        {
            "did": record.did,
            "key_version": record.key_version,
            "status": record.status,
            "reason": record.reason,
            "updated_at": record.updated_at,
        },
    )

def _post_credentials(self, tenant: str) -> None:
    data = self._read_json()
    self._require_fields(data, ("issuer_did", "subject_did"))
    if "claims" not in data:
        raise ValidationError("缺少字段: claims")
    if not isinstance(data["claims"], dict):
        raise ValidationError("字段 claims 必须为 JSON 对象")
    # expires_at 可选：提供时必须为 UTC 秒精度 Z 格式且严格晚于
    # 当前时刻（否则 400）；未提供传哨兵，正文不注入该字段，
    # 凭证保持无期限。
    expires_at = (
        data["expires_at"] if "expires_at" in data else EXPIRES_AT_UNSET
    )
    record = store.create_credential(
        tenant,
        data["issuer_did"],
        data["subject_did"],
        data["claims"],
        expires_at=expires_at,
    )
    self._send_json(
        201,
        {
            "credential_id": record.credential_id,
            "signature": record.signature,
            "issuer_key_version": record.body["issuer_key_version"],
        },
    )

def _post_credentials_status_export(self, tenant: str) -> None:
    # POST /v1/credentials/status-export：新增凭证状态签名发布。
    # 请求体恰为 {"credential_ids": [字符串...]}，数组 1..100 项，
    # 值非空且不重复；结构、类型或数量非法一律 400 且恰返
    # {"error":"请求非法"}。租户头沿用既有缺省、空值与隔离规则。
    # 批初原子读取状态与密钥：任一凭证未知或跨租户 404（恰返
    # {"error":"资源不存在"}），签发 DID 停用 409（恰返
    # {"error":"签发DID已停用"}），均整批失败。成功 200 仅返
    # {"items":[...]}，与输入等长同序，项键序 body、signature，
    # body 键序 issuer_did、credential_id、status、updated_at、
    # issuer_key_version（suspended/revoked 末加 reason）。签名
    # 可直接提交 /v1/trust/credential-status/sync-batch。接口纯
    # 只读：不写状态、历史或审计。
    try:
        length = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(length) if length > 0 else b""
    except (ValueError, TypeError):
        self._send_json(400, {"error": "请求非法"})
        return
    if not raw:
        self._send_json(400, {"error": "请求非法"})
        return
    try:
        data = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        self._send_json(400, {"error": "请求非法"})
        return
    invalid = (
        not isinstance(data, dict)
        or set(data) != {"credential_ids"}
        or not isinstance(data.get("credential_ids"), list)
        or not 1 <= len(data["credential_ids"]) <= 100
        or not all(
            isinstance(value, str) and value != ""
            for value in data["credential_ids"]
        )
        or len(set(data["credential_ids"]))
        != len(data["credential_ids"])
    )
    if invalid:
        self._send_json(400, {"error": "请求非法"})
        return

    try:
        items = store.export_credential_statuses(
            tenant, list(data["credential_ids"])
        )
    except NotFoundError:
        # 任一凭证未知或跨租户：存在性不可探测，整批失败。
        self._send_json(404, {"error": "资源不存在"})
        return
    except ConflictError:
        # 任一签发 DID 已生命周期停用：整批失败。
        self._send_json(409, {"error": "签发DID已停用"})
        return
    self._send_json(200, {"items": items})

def _get_credential(self, tenant: str, credential_id: str) -> None:
    record = store.get_credential(tenant, credential_id)
    self._send_json(
        200,
        {
            "credential_id": record.credential_id,
            "body": record.body,
            "signature": record.signature,
        },
    )

@staticmethod
def _status_payload(record: Any) -> Dict[str, Any]:
    return {
        "credential_id": record.credential_id,
        "status": record.status,
        "updated_at": record.updated_at,
    }

def _put_credential_status(
    self, tenant: str, credential_id: str
) -> None:
    # 请求体必须恰为 {"status": "active"} 或
    # {"status": "suspended", "reason": "原因"}：缺字段、取值
    # 非法、多余字段一律 400；reason 须为字符串且首尾裁剪后为
    # 1..256 个 Unicode 码点，否则 400。
    data = self._read_json()
    if "status" not in data:
        raise ValidationError("缺少字段: status")
    status = data["status"]
    if status == "active":
        extra = sorted(set(data) - {"status"})
        if extra:
            raise ValidationError(
                f"多余字段: {', '.join(extra)}"
            )
        record, created = store.set_credential_status(
            tenant, credential_id, "active"
        )
    elif status == "suspended":
        extra = sorted(set(data) - {"status", "reason"})
        if extra:
            raise ValidationError(
                f"多余字段: {', '.join(extra)}"

def verify_credential(
    self,
    tenant_id: str,
    credential_id: str,
    body: Dict[str, Any],
    signature: str,
) -> Tuple[bool, str]:
    """以存储记录为锚验签：返回 (是否有效, 失败原因)。

    锚定字段为存储的 credential_id、issuer_did、issuer_key_version；
    验签公钥按 issuer_key_version 从签发者公钥历史中取出（旧凭证
    缺版本按 1 处理）。资源查找限本租户（他租户凭证按不存在）。
    任何失败都返回非空中文原因，绝不抛异常、绝不泄露私钥。
    reason 按类别区分：请求 / 资源 / 锚定 / 签名格式 / 签名校验 /
    密钥。验签不记审计。
    """
    if not isinstance(body, dict):
        return False, "请求不合法: 字段 body 必须为 JSON 对象"
    if not isinstance(signature, str) or not signature:
        return False, "请求不合法: 字段 signature 必须为非空字符串"

    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        rec = (
            bucket["credentials"].get(credential_id)
            if bucket is not None else None
        )
        if rec is None:
            return False, f"凭证不存在: {credential_id}"
        stored_body = rec["body"]

        if body.get("credential_id") != stored_body.get("credential_id"):
            return False, (
                "锚定校验失败: 正文 credential_id 与存储记录不一致"
            )
        if body.get("issuer_did") != stored_body.get("issuer_did"):
            return False, "锚定校验失败: 正文 issuer_did 与存储记录不一致"
        stored_version = stored_body.get("issuer_key_version", 1)
        if body.get("issuer_key_version", 1) != stored_version:
            return False, (
                "锚定校验失败: 正文 issuer_key_version 与存储记录不一致"
            )

        issuer_did = stored_body.get("issuer_did")
        public_pem = self._public_key_for_version_locked(
            bucket, issuer_did, stored_version
        )
        issuer_entry = self._key_history_entry_by_version_locked(
            bucket, issuer_did, stored_version
        )
        # 签发者 DID 的停用判定在锚定与验签成功后进行；锁内捕获状态。
        issuer_row = (
            bucket["dids"].get(issuer_did)
            if issuer_did is not None
            else None
        )
        issuer_did_deactivated = self._is_did_deactivated_locked(
            issuer_row
        )
        issuer_did_deactivate_reason = (
            issuer_row.get("deactivate_reason")
            if issuer_row is not None
            else None
        )
        # 签发密钥版本的吊销判定在验签成功后进行；锁内捕获状态。
        issuer_key_revoked = (
            issuer_entry is not None
            and issuer_entry.get("status") == "revoked"
        )
        issuer_key_revoke_reason = (
            issuer_entry.get("revoke_reason") if issuer_entry is not None else None
        )
        # 状态在锚定、签名校验成功后才参与判定；active 或无状态维持结果
        credential_status = rec.get("status")
        revoke_reason = rec.get("revoke_reason")
        suspend_reason = rec.get("suspend_reason")

    if not public_pem:
        return False, (
            "历史公钥不可用: 签发者 "
            f"{issuer_did} 密钥版本 {stored_version} 的公钥不存在"
        )
    try:
        crypto.validate_public_key_pem(public_pem)
    except (ValueError, TypeError):
        return False, (
            "历史公钥不可用: 签发者 "
            f"{issuer_did} 密钥版本 {stored_version} 的公钥无法解析"
        )

    try:
        crypto.verify(body, signature, public_pem)
    except crypto.MalformedSignature:
        return False, "签名格式错误: 不是合法的 ES256 签名编码"
    except crypto.InvalidSignature:
        return False, "签名校验失败，正文或签名可能被改动"
    except Exception:  # noqa: BLE001 验签绝不向上抛错或泄露内部细节
        return False, "验签过程发生内部错误"

    # 验签成功后按“签发密钥 -> 签发者 DID 停用 -> 有效期 -> 凭证吊销”
    # 顺序判定：签发密钥版本被吊销时 valid:false，沿用原分类协议。
    if issuer_key_revoked:
        saved_reason = issuer_key_revoke_reason or DEFAULT_KEY_REVOKE_REASON
        return False, f"签发密钥已吊销：{saved_reason}"

    # 锚定与签名均成功后检查签发者 DID 是否已停用：valid:false，
    # 优先于凭证有效期与凭证吊销（只读判定，不记审计）。
    if issuer_did_deactivated:
        saved_reason = (
            issuer_did_deactivate_reason
            or DEFAULT_DID_DEACTIVATE_REASON
        )
        return False, f"{DID_DEACTIVATED_REASON_PREFIX}{saved_reason}"

    # 签名、锚定均成功后检查有效期：当前时间 >= expires_at 判
    # valid:false（只读，不记审计）；无 expires_at 的旧凭证无期限。
    # 其余失败（请求/资源/锚定/签名）已在上方优先返回原分类原因。
    if _is_expired(stored_body.get("expires_at")):
        return False, CREDENTIAL_EXPIRED_REASON

    # 签名、锚定均成功后检查状态：suspended/revoked 判 valid:false，
    # 判定位置相同（有效期之后）；active 或历史无状态维持 valid:true
    if credential_status == "suspended":
        saved_reason = suspend_reason or "未知原因"
        return False, f"{CREDENTIAL_SUSPENDED_REASON_PREFIX}{saved_reason}"
    if credential_status == "revoked":
        saved_reason = revoke_reason or DEFAULT_REVOKE_REASON
        return False, f"凭证已吊销：{saved_reason}"
    return True, ""

# ------------------------------------------------------------------ #
# 信任锚点注册表
# ------------------------------------------------------------------ #
@staticmethod
def _trust_anchor_record(did: str, row: Dict[str, Any]) -> TrustAnchorRecord:
    return TrustAnchorRecord(
        did=did,
        public_key=row["public_key"],
        key_version=int(row["key_version"]),
        status=row.get("status", "active"),

def _post_verify_credential(
    self, tenant: str, credential_id: str
) -> None:
    # verify 端点的公开错误协议：任何“验签失败”都返回 200 +
    # {"valid": false, "reason": "<非空中文原因>"}，绝不返回
    # 404/500，也不泄露私钥或堆栈。reason 按类别措辞：
    # 请求层（请求*）、资源（凭证不存在）、锚定、签名、密钥。
    try:
        length = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(length) if length > 0 else b""
    except (ValueError, TypeError):
        self._send_invalid("请求体缺失或长度声明非法")
        return
    except Exception:  # noqa: BLE001
        self._send_invalid("请求体读取失败")
        return
    if not raw:
        self._send_invalid("请求体缺失")
        return
    try:
        data = json.loads(raw.decode("utf-8"))
    except UnicodeDecodeError:
        self._send_invalid("请求体不是合法 UTF-8 文本")
        return
    except json.JSONDecodeError:
        self._send_invalid("请求体不是合法 JSON")
        return
    if not isinstance(data, dict):
        self._send_invalid("请求体必须为 JSON 对象")
        return
    if "body" not in data:
        self._send_invalid("请求缺少字段: body")
        return
    if not isinstance(data["body"], dict):
        self._send_invalid("请求字段 body 必须为 JSON 对象")
        return
    if "signature" not in data:
        self._send_invalid("请求缺少字段: signature")
        return
    if not isinstance(data["signature"], str) or not data["signature"]:
        self._send_invalid("请求字段 signature 必须为非空字符串")
        return

    try:
        valid, reason = store.verify_credential(
            tenant, credential_id, data["body"], data["signature"]
        )
    except Exception:  # noqa: BLE001 验签失败绝不暴露内部细节
        self._send_invalid("验签过程发生内部错误")
        return
    payload: Dict[str, Any] = {"valid": valid}
    if not valid:
        payload["reason"] = reason or "验签失败"
    self._send_json(200, payload)

@staticmethod
def _presentation_payload(
    record: PresentationRecord,
) -> Dict[str, Any]:
    """按对外契约的固定键序组装演示对象。

    未绑定恰为九字段；持有者绑定在末尾追加 holder_did、
    holder_key_version、holder_proof。
    """
    payload: Dict[str, Any] = {
        "presentation_id": record.presentation_id,
        "credential_id": record.credential_id,
        "issuer_did": record.issuer_did,
        "issuer_key_version": record.issuer_key_version,
        "disclose": record.disclose,
        "claims": record.projection,
        "challenge": record.challenge,
        "expires_at": record.expires_at,
        "proof": record.proof,
    }
    # 仅持有者绑定演示返回 holder_did、holder_key_version、
    # holder_proof；未绑定响应字段集合与旧流程完全一致。
    if record.holder_did is not None:
        payload["holder_did"] = record.holder_did
        payload["holder_key_version"] = (
            record.holder_key_version
        )
        payload["holder_proof"] = record.holder_proof
    return payload

@staticmethod
def _validate_present_item(
    item: Any, index: int
) -> Dict[str, Any]:
    """校验单个演示生成项，返回透传给 store 的关键字参数。

    规则与单项 present 完全一致：项须为对象，恰含 disclose 及
    可选 challenge、expires_in、holder_binding；challenge 为非空
    字符串且按 Unicode 码点不超过 256；expires_in 为非布尔整数
    且在 1..86400；holder_binding 为布尔。index 为从 0 起的项
    序号，错误信息带从 1 起的中文项号。
    """
    where = f"第 {index + 1} 项"
    if not isinstance(item, dict):
        raise ValidationError(f"{where}必须为 JSON 对象")
    if "disclose" not in item:
        raise ValidationError(f"{where}缺少字段: disclose")
    extra = sorted(
        set(item)
        - {"disclose", "challenge", "expires_in", "holder_binding"}
    )
    if extra:
        raise ValidationError(
            f"{where}含多余字段: {', '.join(extra)}"
        )

"""ES256 签名与规范化 JSON。

ES256 即 ECDSA over P-256 与 SHA-256。签名以 JWS 约定编码：
64 字节裸 R||S 的 base64url（无填充）。cryptography 库签出的是 DER，
这里在 DER 与 R||S 之间做转换。
"""

import base64
import json
import re
from typing import Any, Dict

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import ec
from cryptography.hazmat.primitives.asymmetric.utils import (
    decode_dss_signature,
    encode_dss_signature,
)

__all__ = [
    "InvalidSignature",
    "MalformedSignature",
    "canonicalize",
    "generate_private_key_pem",
    "public_key_pem_from_private",
    "validate_public_key_pem",
    "validate_signature_format",
    "validate_signature_format_strict",
    "sign",
    "verify",
]


class MalformedSignature(ValueError):
    """签名编码格式非法（无法解码或不是 64 字节裸 R||S）。"""


def _b64url(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")


def _b64url_decode(text: str) -> bytes:
    padding = "=" * (-len(text) % 4)
    return base64.urlsafe_b64decode(text + padding)


def canonicalize(body: Dict[str, Any]) -> bytes:
    """正文按 key 升序的规范化 JSON 序列化（紧凑、UTF-8 字节）。"""
    return json.dumps(
        body, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def generate_private_key_pem() -> str:
    """生成 P-256 私钥，返回 PKCS8 PEM 字符串。"""
    private_key = ec.generate_private_key(ec.SECP256R1())
    pem = private_key.private_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PrivateFormat.PKCS8,
        encryption_algorithm=serialization.NoEncryption(),
    )
    return pem.decode("utf-8")


def public_key_pem_from_private(private_pem: str) -> str:
    """从私钥 PEM 导出对应的 SubjectPublicKeyInfo 公钥 PEM。"""
    private_key = serialization.load_pem_private_key(
        private_pem.encode("utf-8"), password=None
    )
    if not isinstance(private_key, ec.EllipticCurvePrivateKey):
        raise ValueError("私钥不是 P-256 椭圆曲线私钥")
    if not isinstance(private_key.curve, ec.SECP256R1):
        raise ValueError("私钥曲线不是 P-256")
    pem = private_key.public_key().public_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PublicFormat.SubjectPublicKeyInfo,
    )
    return pem.decode("utf-8")


def _load_public_key(public_pem: str) -> ec.EllipticCurvePublicKey:
    try:
        key = serialization.load_pem_public_key(public_pem.encode("utf-8"))
    except (ValueError, TypeError) as exc:
        raise ValueError(f"公钥 PEM 无法解析: {exc}") from exc
    if not isinstance(key, ec.EllipticCurvePublicKey) or not isinstance(
        key.curve, ec.SECP256R1
    ):
        raise ValueError("公钥不是 P-256 椭圆曲线公钥")
    return key


def validate_public_key_pem(public_pem: str) -> None:
    """校验公钥 PEM 可解析且为 ES256 所需的 P-256 公钥，否则抛 ValueError。"""
    _load_public_key(public_pem)


def _load_private_key(private_pem: str) -> ec.EllipticCurvePrivateKey:
    try:
        key = serialization.load_pem_private_key(
            private_pem.encode("utf-8"), password=None
        )
    except (ValueError, TypeError) as exc:
        raise ValueError(f"私钥 PEM 无法解析: {exc}") from exc
    if not isinstance(key, ec.EllipticCurvePrivateKey) or not isinstance(
        key.curve, ec.SECP256R1
    ):
        raise ValueError("私钥不是 P-256 椭圆曲线私钥")
    return key


def sign(body: Dict[str, Any], private_pem: str) -> str:
    """对规范化正文做 ES256 签名，返回 base64url(R||S)。"""
    private_key = _load_private_key(private_pem)
    der = private_key.sign(
        canonicalize(body), ec.ECDSA(hashes.SHA256())
    )
    r, s = decode_dss_signature(der)
    raw = r.to_bytes(32, "big") + s.to_bytes(32, "big")
    return _b64url(raw)


def validate_signature_format(signature_b64: str) -> None:
    """校验签名编码格式：须为可解码的 base64url 且裸 R||S 恰为 64 字节。

    仅检查格式，不做密码学验签。格式非法抛 MalformedSignature。
    """
    try:
        raw = _b64url_decode(signature_b64)
    except Exception as exc:  # noqa: BLE001 解码异常（含 binascii）均属格式问题
        raise MalformedSignature("签名不是合法的 base64url 编码") from exc
    if len(raw) != 64:
        raise MalformedSignature("签名长度不是 64 字节，非合法 ES256 签名")


# 严格格式：64 字节裸 R||S 的无填充 base64url 恰为 86 个字符
_RAW_RS_B64URL_STRICT_RE = re.compile(r"[A-Za-z0-9_-]{86}")


def validate_signature_format_strict(signature_b64: str) -> None:
    """严格校验签名编码格式：恰为 86 个 base64url 字符（无填充、无字
    母表外字符），解码恰为 64 字节裸 R||S，且无填充 base64url 重编码
    与原文逐字符一致（排除填充与非规范尾位）。

    仅检查格式，不做密码学验签。格式非法抛 MalformedSignature。
    """
    if not isinstance(signature_b64, str) or not (
        _RAW_RS_B64URL_STRICT_RE.fullmatch(signature_b64)
    ):
        raise MalformedSignature(
            "签名不是 86 字符的无填充 base64url 编码"
        )
    raw = _b64url_decode(signature_b64)
    if len(raw) != 64 or _b64url(raw) != signature_b64:
        raise MalformedSignature(
            "签名不是规范的 64 字节裸 R||S 无填充 base64url 编码"
        )


def verify(body: Dict[str, Any], signature_b64: str, public_pem: str) -> None:
    """校验签名：格式非法抛 MalformedSignature，验签失败抛 InvalidSignature。"""
    validate_signature_format(signature_b64)
    public_key = _load_public_key(public_pem)
    raw = _b64url_decode(signature_b64)
    r = int.from_bytes(raw[:32], "big")
    s = int.from_bytes(raw[32:], "big")
    der = encode_dss_signature(r, s)
    public_key.verify(der, canonicalize(body), ec.ECDSA(hashes.SHA256()))

